/***************************************************************************************
 *  File: AttConfig.h
 *
 *  台架姿态估计的集中配置：采样率、滤波器、Mahony 参数、串口节奏。
 *  所有可调项都放在这里，改采样率/截止频率只需改本文件。
 ****************************************************************************************/
#ifndef __ATT_CONFIG_H__
#define __ATT_CONFIG_H__

// =====================================================================================
// 运行入口
// =====================================================================================
// 1: 主循环运行台架姿态估计（只读 IMU + 串口文本，不进入旧遥控/控制/混控/气压）
// 0: 保持原工程行为
#define C_ATT_BENCH_EN          1

// =====================================================================================
// 采样
// =====================================================================================
// MCU 读取率。传感器本身固定 800Hz 输出；首版默认 200Hz，后续实测可改 400。
#define C_ATT_SAMPLE_HZ         200
// 采样节拍（tick）在 AttBench.c 里按 CLOCK_SYS_CLOCK_HZ 换算

// =====================================================================================
// T-3488 量程与灵敏度（与 my_t3488.h 的配置一致）
// =====================================================================================
#define C_ACC_LSB_PER_G         2048.0f     // ±16g
#define C_GYRO_LSB_PER_DPS      16.4f       // ±2000dps
#define C_DEG_TO_RAD            0.01745329252f

// =====================================================================================
// 陀螺仪片内 UI 低通（IPREG SYS1 偏移 0x09，bit[2:0]）
//   800Hz ODR 下：0=ODR/2(400Hz) 1=ODR/4(200Hz) 2=ODR/8(100Hz) 3=ODR/16(50Hz)
//   台架初值取 ODR/16 = 50Hz；陀螺仪软件侧不再叠加低通。
// =====================================================================================
#define C_GYRO_LPF_SEL          3
#define C_GYRO_LPF_HZ_NOMINAL   50      // 仅用于串口显示

// =====================================================================================
// 加速度一阶低通（在校准后的机体 FRD 上做，三轴同一截止频率）
//   C_ACC_LPF_EN=0 时旁路；时间常数 τ = 1/(2π·fc)，默认 30Hz → 5305us
// =====================================================================================
#define C_ACC_LPF_EN            1
#define C_ACC_LPF_TAU_US        5305

// =====================================================================================
// Mahony 互补滤波
// =====================================================================================
#define C_MAHONY_KP_Q15         16384       // 0.5（慢速纠正）
#define C_ATT_INIT_SAMPLES      100         // 上电静止样本数：200Hz 下约 0.5s
#define C_ATT_TRUST_MIN_MG      700         // 0.70g 以下：暂停纠偏
#define C_ATT_TRUST_FULL_LO_MG  850         // 0.85g 起：完全信任
#define C_ATT_TRUST_FULL_HI_MG  1150        // 1.15g 以内：完全信任
#define C_ATT_TRUST_MAX_MG      1300        // 1.30g 以上：暂停纠偏

// =====================================================================================
// 采样连续性
// =====================================================================================
// 相邻有效样本的间隔超过此值：认为长间断，重新建立积分端点，不用单拍补算整段
#define C_ATT_MAX_GAP_100US     1000    // 100ms

// =====================================================================================
// 串口输出（沿用现有 UART0，115200-8-N1）
// =====================================================================================
#define C_ATT_TX_HZ             14          // 姿态文本约 14Hz
// 输出节拍（tick）同样在 AttBench.c 里换算

#endif // __ATT_CONFIG_H__
